626		dir := t.TempDir()
627		receive := testBase
628		r1 := hb("n1", 1, receive.Add(-time.Minute), "1.0", 100, 0)
629		r2 := hb("n1", 1, receive.Add(-time.Minute), "2.0", 100, 0)
630	
631		var mu sync.Mutex
632		successes := 0
633		conflicts := 0
634		var errs []error
635		var wg sync.WaitGroup
636		for i := 0; i < 20; i++ {
637			wg.Add(1)
638			go func(i int) {
